import os

BASE_DIR = '/var/www/fina-connect'

print("⏳ 1/3 Rješavam Ruter (urls.py) i brišem grešku...")
with open(os.path.join(BASE_DIR, 'website/urls.py'), 'w', encoding='utf-8') as f:
    f.write("""from django.urls import path\nfrom . import views\nfrom . import cms_views\n\napp_name = 'website'\n\nurlpatterns = [\n    path('cms/gallery/', cms_views.cms_gallery, name='cms_gallery'),\n    path('cms/gallery/toggle/<int:id>/', cms_views.toggle_img, name='toggle_img'),\n    path('', views.homepage, name='homepage'),\n    path('bau/', views.bau_page, name='bau_page'),\n    path('admin-panel/', views.admin_panel, name='admin_panel'),\n    path('hitna-intervencija/', views.hitna_intervencija, name='hitna_intervencija'),\n    path('hitna-intervencija/hvala/', views.hitna_hvala, name='hitna_hvala'),\n    path('video-galerija/', views.video_galerija, name='video_galerija'),\n    path('hr/', views.viskovic_hr, name='viskovic_hr'),\n]\n""")

print("⏳ 2/3 Forsiram Tamnu Temu i Prave Linkove u CMS Dashboardu...")
with open(os.path.join(BASE_DIR, 'templates/website/index.html'), 'w', encoding='utf-8') as f:
    f.write("""{% extends 'base.html' %}\n{% load i18n %}\n{% block title %}Web Portal CMS{% endblock %}\n{% block page_title %}Zentrales Web Management{% endblock %}\n{% block content %}\n<div style="background-color: #0f172a; color: #f8fafc; min-height: 80vh; padding: 30px; border-radius: 12px; border: 1px solid #334155;">\n    <div style="border-bottom: 1px solid #334155; padding-bottom: 20px; margin-bottom: 30px; display: flex; justify-content: space-between; align-items: center;">\n        <div>\n            <h1 style="font-family: 'Barlow Condensed', sans-serif; font-size: 2.2rem; color: #c9a84c; text-transform: uppercase; margin: 0;">Web Portal CMS</h1>\n            <div style="color: #94a3b8; font-size: 0.95rem; margin-top: 5px;">Centralno zapovjedno mjesto za viskovic-group.de</div>\n        </div>\n        <a href="/" target="_blank" style="background: #1e293b; color: #f8fafc; border: 1px solid #334155; padding: 10px 20px; border-radius: 8px; text-decoration: none;"><i class="fas fa-external-link-alt"></i> Pregledaj Web</a>\n    </div>\n    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 24px;">\n        <div style="background: #1e293b; border: 1px solid #334155; border-radius: 12px; padding: 24px; display: flex; flex-direction: column;">\n            <div style="display: flex; align-items: center; gap: 15px; margin-bottom: 20px;">\n                <div style="width: 50px; height: 50px; border-radius: 10px; background: rgba(201, 168, 76, 0.1); color: #c9a84c; display: flex; align-items: center; justify-content: center; font-size: 1.5rem;"><i class="fas fa-camera"></i></div>\n                <h2 style="font-size: 1.3rem; font-weight: 700; margin: 0; color: #f8fafc;">Foto Galerija</h2>\n            </div>\n            <p style="color: #94a3b8; font-size: 0.85rem; margin-bottom: 20px;">Upravljanje slikama na javnom portalu. Ukupno: <strong>{{ gallery.count }}</strong></p>\n            <a href="/website/cms/gallery/" style="background: #1e293b; color: #f8fafc; border: 1px solid #334155; padding: 12px 15px; border-radius: 8px; text-decoration: none; font-weight: 600; text-align: center; margin-top: auto; text-transform: uppercase; font-size: 0.85rem;"><i class="fas fa-images"></i> Upravljaj Galerijom</a>\n        </div>\n    </div>\n</div>\n{% endblock %}\n""")

print("⏳ 3/3 Ugrađujem LIVE Galeriju na BAU stranicu...")
bau_path = os.path.join(BASE_DIR, 'website/templates/website/bau.html')
with open(bau_path, 'r', encoding='utf-8') as f:
    bau_html = f.read()

live_gal = """\n<section style="padding: 60px 0; background-color: #050505; border-top: 1px solid #222; margin-top: 40px;">\n    <div class="container">\n        <h2 style="color: #c9a84c; font-family: 'Barlow Condensed', sans-serif; text-transform: uppercase; font-size: 2.5rem; letter-spacing: 2px; margin-bottom: 40px; text-align: center;">Live S Gradilišta</h2>\n        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 24px;">\n            {% if media_items %}\n                {% for item in media_items %}\n                <div style="position: relative; border-radius: 12px; overflow: hidden; border: 1px solid #333; aspect-ratio: 4/3; background: #111;">\n                    {% if item.type == 'image' %}<img src="{{ item.url }}" alt="{{ item.title }}" style="width: 100%; height: 100%; object-fit: cover;">\n                    {% elif item.type == 'video_file' %}<video width="100%" height="100%" style="object-fit: cover;" controls muted playsinline><source src="{{ item.url }}" type="video/mp4"></video>\n                    {% elif item.type == 'video_embed' %}<iframe src="{{ item.url }}" width="100%" height="100%" style="border:none;" allowfullscreen></iframe>\n                    {% endif %}\n                    <div style="position: absolute; bottom: 0; left: 0; width: 100%; padding: 20px; background: linear-gradient(to top, rgba(0,0,0,0.9), transparent); pointer-events: none;"><div style="color: #c9a84c; font-family: 'Barlow Condensed', sans-serif; font-size: 1.4rem; text-transform: uppercase; letter-spacing: 1px; font-weight: bold;">{{ item.title }}</div></div>\n                </div>\n                {% endfor %}\n            {% else %}\n                <div style="grid-column: 1/-1; text-align: center; color: #555; padding: 40px; border: 1px dashed #333; border-radius: 12px;">Nema aktivnih slika.</div>\n            {% endif %}\n        </div>\n    </div>\n</section>\n"""

if "Live S Gradili" not in bau_html:
    bau_html = bau_html.replace('{% endblock %}', live_gal + '{% endblock %}')
    with open(bau_path, 'w', encoding='utf-8') as f:
        f.write(bau_html)

print("✅ SVE JE SPREMNO. Pokrećem restart servera...")
